"use client";
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { inviteStaffMember, revokeStaffAccess, updateStaffPermissions } from "@/app/actions/staff-access";
import type { getVendorStaff } from "@/app/actions/staff";
import s from "@/components/vendor/business-workspace.module.css";
type Member=Awaited<ReturnType<typeof getVendorStaff>>[number];
export default function StaffAccessEditor({member}:{member:Member}) {
 const router=useRouter(),[pending,start]=useTransition(),[message,setMessage]=useState(""),[link,setLink]=useState("");
 const [email,setEmail]=useState(member.access?.email??""),[notes,setNotes]=useState(member.access?.canEditNotes??false),[timeOff,setTimeOff]=useState(member.access?.canManageTimeOff??false);
 const connected=!!member.access?.userId;
 function run(fn:()=>Promise<void>){setMessage("");start(async()=>{try{await fn();router.refresh();}catch(e){setMessage(e instanceof Error?e.message:"Could not update access.");}});}
 return <section className={s.card} style={{background:"#f5f9fa"}}><div className={s.row}><h3 className={s.heading}>Their own login</h3><span className={s.badge}>{!member.isActive?"Access paused":connected?"Connected":member.access?.inviteExpiresAt?new Date(member.access.inviteExpiresAt)>new Date()?"Invitation pending":"Invitation expired":"Not invited"}</span></div><p className={s.muted}>Their personal workspace shows assigned appointments and working hours. Your finances, customers’ contact details and business settings stay with you.</p><form className={s.stack} style={{gap:12,marginTop:15}} onSubmit={e=>{e.preventDefault();run(async()=>{if(connected){await updateStaffPermissions(member.id,{canEditNotes:notes,canManageTimeOff:timeOff});setMessage("Permissions saved.");}else{const r=await inviteStaffMember(member.id,email,{canEditNotes:notes,canManageTimeOff:timeOff});setLink(new URL(r.path,window.location.origin).href);setMessage("Invitation created. Share this link with the named person. It expires in 7 days.");}});}}><label className={s.label}>Email address<input className={s.input} style={{width:"100%",marginTop:6}} type="email" required disabled={connected} value={email} onChange={e=>setEmail(e.target.value)} placeholder="teammate@example.com"/></label><label className={s.muted}><input type="checkbox" checked={notes} onChange={e=>setNotes(e.target.checked)}/> Allow editing shared appointment notes</label><label className={s.muted}><input type="checkbox" checked={timeOff} onChange={e=>setTimeOff(e.target.checked)}/> Allow managing their own time off</label><p className={s.small}>Viewing assigned appointments is included. Changing bookings, payments or other people’s schedules requires the owner.</p><div className={s.toolbar}><button disabled={pending||!member.isActive} className={s.secondary}>{pending?"Saving…":connected?"Save permissions":member.access?"Create replacement invitation":"Create invitation link"}</button>{member.access&&<button type="button" className={s.link} disabled={pending} onClick={()=>{if(!window.confirm("Revoke this person's login and pending invitation? Appointments and schedules will be kept."))return;run(async()=>{await revokeStaffAccess(member.id);setLink("");setMessage("Access revoked. Appointment history is kept.");});}}>Revoke access</button>}</div></form>{message&&<p role="status" className={s.muted} style={{marginTop:12}}>{message}</p>}{link&&<div className={s.stack} style={{marginTop:12,gap:8}}><input aria-label="Invitation link" className={s.input} readOnly value={link} onFocus={e=>e.target.select()}/><button className={s.secondary} onClick={async()=>{try{await navigator.clipboard.writeText(link);setMessage("Invitation link copied.");}catch{setMessage("Select the invitation link and copy it manually.");}}}>Copy invitation link</button><p className={s.small}>Use an existing LinkWe account or create a customer account with this email, verify it, then open this link to join. Creating a replacement invalidates the previous link.</p></div>}</section>;
}
